-- ============================================================
-- Section becomes many-to-many, like discipline and content category
--
-- FOUND BY THE VERIFIER, not by reading the schema. The section-compatibility
-- check failed on 4 of 2,242 mappings, all on one concept:
--
--   "Isoelectric Focusing" is taught in two chapters and classified under two
--   MCAT sections. 4 questions sit in chem_phys under Electrochemistry, and 4
--   in bio_biochem under Non-enzymatic Protein Function and Protein Analysis.
--   Both are biochemistry. It is one technique, examined from two directions.
--
-- The seeder had to choose one and chose arbitrarily, so 4 questions ended up
-- mapped to a concept whose section contradicted their own.
--
-- THE FIX IS THE ONE THE ARCHITECTURE ALREADY ARGUED FOR. Discipline and
-- content category were both made many-to-many precisely because forcing a
-- single parent misfiles real science. Section was left singular, which was an
-- oversight: the approved target model said section_ids, plural. This corrects
-- that inconsistency rather than splitting a genuine single concept in two or
-- relaxing the validation to hide the conflict.
--
-- Only one concept spans sections today. It is still worth fixing structurally,
-- because the alternative is a validation rule nobody can enforce and a slow
-- accumulation of arbitrary choices as Physics and Psych/Soc content arrives.
--
-- Additive and reversible. No question, flashcard, mapping, FSRS state, review
-- or attempt is touched; only where a concept's section is recorded changes.
-- ============================================================

CREATE TABLE IF NOT EXISTS public.concept_sections (
  concept_id   UUID NOT NULL REFERENCES public.concepts(id) ON DELETE CASCADE,
  section_code TEXT NOT NULL REFERENCES public.mcat_sections(code),
  is_primary   BOOLEAN NOT NULL DEFAULT TRUE,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (concept_id, section_code)
);

COMMENT ON TABLE public.concept_sections IS
  'Which MCAT sections a concept is examined in. Many-to-many because a concept can legitimately appear in two: isoelectric focusing is both an electrochemistry topic and a protein-analysis one. is_primary marks where most of its questions sit, for display; validation must check MEMBERSHIP, not equality.';

CREATE UNIQUE INDEX IF NOT EXISTS concept_sections_one_primary
  ON public.concept_sections(concept_id) WHERE is_primary;
CREATE INDEX IF NOT EXISTS concept_sections_section_idx
  ON public.concept_sections(section_code);

ALTER TABLE public.concept_sections ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "read taxonomy" ON public.concept_sections;
CREATE POLICY "read taxonomy" ON public.concept_sections
  FOR SELECT USING (auth.role() = 'authenticated');

ON CONFLICT (concept_id, section_code) DO NOTHING;
-- The singular column is now a second source of truth for the same fact, and
-- for one concept it holds the wrong half of it. Dropped rather than kept in
-- sync, because two places to look is how drift starts.
ALTER TABLE public.concepts DROP COLUMN IF EXISTS section_code;

-- ── Verification ────────────────────────────────────────────────────────
SELECT
  (SELECT count(*) FROM public.concept_sections)                              AS section_rows,    -- 489
  (SELECT count(DISTINCT concept_id) FROM public.concept_sections)            AS concepts_placed, -- 488
  (SELECT count(*) FROM (SELECT concept_id FROM public.concept_sections
     GROUP BY concept_id HAVING count(*) > 1) x)                              AS multi_section,   -- 1
  (SELECT count(*) FROM public.question_concepts)                             AS mappings_intact, -- 2242
  (SELECT count(*) FROM public.questions)                                     AS questions_intact,-- 2681
  (SELECT count(*) FROM public.flashcards)                                    AS cards_intact;    -- 4117

-- Section compatibility, now by MEMBERSHIP. Expect zero rows.
SELECT 'section mismatch' AS problem, count(*) AS n
FROM public.question_concepts qc
JOIN public.questions q ON q.id = qc.question_id
JOIN public.legacy_taxonomy_map m
  ON m.source_system='questions' AND m.source_field='section' AND m.source_value=q.section
WHERE NOT EXISTS (
  SELECT 1 FROM public.concept_sections cs
  WHERE cs.concept_id = qc.concept_id AND cs.section_code = m.section_code);

-- The concept that prompted this.
SELECT c.canonical_name, cs.section_code, cs.is_primary
FROM public.concepts c JOIN public.concept_sections cs ON cs.concept_id = c.id
WHERE c.slug = 'ISOELECTRIC_FOCUSING' ORDER BY cs.is_primary DESC;

